# Medicine guides batch 3 (19 Nov 2026): antibiotics.
V, C, U, R, VR = ("v", "Very common", "more than 1 in 10"), ("c", "Common", "1 in 10 to 1 in 100"), ("u", "Uncommon", "1 in 100 to 1 in 1,000"), ("r", "Rare", "1 in 1,000 to 1 in 10,000"), ("vr", "Very rare", "fewer than 1 in 10,000")
def g(t, items): return (t[0], t[1], t[2], items)
PBS = "https://www.pbs.gov.au/pbs/search?term="
AMR = ("Australian Commission on Safety and Quality in Health Care: Antimicrobial resistance", "https://www.safetyandquality.gov.au/our-work/antimicrobial-resistance")
REL = [("Antibiotics", "/antibiotics/"), ("Antibiotic resistance deep dive", "/deep-dives/")]

med("amoxicillin", "Amoxicillin and Amoxicillin-Clavulanate (Augmentin): Uses and Side Effects",
 "Amoxicillin and amoxicillin with clavulanic acid (Augmentin) explained: what infections they treat, dose, diarrhoea and rash, penicillin allergy and why they don’t help colds.",
 "Amoxicillin and Augmentin", "Amoxicillin",
 [("s", "Penicillin antibiotic"), ("l", "Prescription only (S4)")],
 "The most prescribed antibiotic in Australia, from the penicillin family. Augmentin adds clavulanic acid to beat bacteria that would otherwise destroy amoxicillin.",
 "Amoxicillin treats common bacterial infections such as strep throat, ear and sinus infections and chest infections. Augmentin (amoxicillin with clavulanic acid) covers more bacteria and is used for bites, some skin and more complicated infections, at the cost of more diarrhoea. Neither helps colds, flu or most sore throats, which are viral.",
 [("For", "Bacterial ear, sinus, throat and chest infections; Augmentin for bites, some skin and urine infections"),
  ("Works", "Very effective against susceptible bacteria; no effect on viruses"),
  ("Cost", "PBS: $25 a script ($7.70 concession), often less"),
  ("Kicks in", "Most people feel better in 2 to 3 days"),
  ("Dose", "Commonly 500 mg three times a day or 1 g twice a day; children by weight"),
  ("Watch for", "Diarrhoea, thrush, rash; allergy")],
 "A brilliant antibiotic that’s wasted on colds.",
 ["Amoxicillin: Amoxil, Alphamox, Moxacin. Amoxicillin with clavulanic acid: Augmentin, Augmentin Duo Forte, Clamoxyl, Curam"],
 "Amoxicillin stops bacteria building their cell walls, so they burst. Some bacteria make an enzyme (beta-lactamase) that breaks amoxicillin down; clavulanic acid blocks that enzyme.",
 ["Ear infections (when antibiotics are needed), sinusitis and strep throat",
  "Community-acquired pneumonia",
  "Augmentin: animal and human bites, some skin infections, dental infections, some urine infections",
  "Part of H. pylori eradication treatment",
  "Not for colds, flu, most coughs or viral sore throats"],
 "Usually well tolerated. Gut upset is the most common side effect, more so with Augmentin.",
 [g(C, ["Diarrhoea (Augmentin more than amoxicillin)", "Nausea", "Thrush (mouth or vaginal)", "Rash"]),
  g(U, ["Hives and itch"]),
  g(R, ["<b>Anaphylaxis</b>", "<b>C. difficile diarrhoea</b>", "<b>Liver problems</b> (Augmentin, usually in older people)", "<b>Severe skin reactions</b>"])],
 ["Swelling of face, lips or throat, or trouble breathing: call 000", "Severe or bloody diarrhoea, even weeks later", "Yellow skin or eyes", "Blistering or peeling rash"],
 ["Tell your doctor about any penicillin allergy. Many people labelled allergic aren’t: a GP or allergy service can test and remove a wrong label.", "A flat, non-itchy rash with amoxicillin during glandular fever is common and isn’t a true allergy.", "Take Augmentin with food to reduce nausea.", "Finish the course your doctor recommends; shorter courses are now common for many infections."],
 [("Is amoxicillin a penicillin?", "Yes. Avoid it if you’ve had a true penicillin allergy, and tell your doctor or pharmacist."),
  ("What’s the difference between amoxicillin and Augmentin?", "Augmentin adds clavulanic acid, which protects amoxicillin from bacteria that would break it down. It covers more infections but causes more diarrhoea."),
  ("Does amoxicillin help a cold or flu?", "No. Colds and flu are viruses, and antibiotics don’t work on them. Unneeded antibiotics cause side effects and resistance."),
  ("Can I drink alcohol on amoxicillin?", "Moderate drinking doesn’t interact with amoxicillin, though rest and fluids help you recover.")],
 [AMR, ("PBS: Amoxicillin", PBS + "amoxicillin"), ("ASCIA: Penicillin allergy", "https://www.allergy.org.au/patients/drug-allergy/penicillin-allergy")],
 REL + [("Sore throat", "/sore-throat/")])

med("cefalexin", "Cefalexin (Keflex): Uses, Side Effects and Penicillin Allergy",
 "Cefalexin explained: skin, urine and other infections it treats, dose, side effects, and whether people with penicillin allergy can take it.",
 "Cefalexin", "Cefalexin",
 [("s", "Cephalosporin antibiotic"), ("l", "Prescription only (S4)")],
 "A first-generation cephalosporin antibiotic, commonly used for skin infections like cellulitis, and some urine infections, including in pregnancy.",
 "Cefalexin treats skin and soft tissue infections (cellulitis, infected wounds), some urine infections and some other infections. It’s related to penicillin, but most people with a mild penicillin allergy can take it safely; people with a severe penicillin reaction should check first.",
 [("For", "Cellulitis and skin infections, urine infections, some bone and joint infections"),
  ("Works", "Effective against common skin bacteria (streptococci and staph, not MRSA)"),
  ("Cost", "PBS: $25 a script ($7.70 concession), often less"),
  ("Kicks in", "Skin infections should start improving within 2 to 3 days"),
  ("Dose", "Commonly 500 mg four times a day for skin infections"),
  ("Watch for", "Diarrhoea, nausea, rash")],
 "The skin infection workhorse.",
 ["Keflex, Ibilex, Cefalexin Sandoz and other generics"],
 "Like penicillins, cefalexin blocks bacteria from building their cell walls.",
 ["Cellulitis and other skin and soft tissue infections",
  "Urine infections, including in pregnancy",
  "Some bone and joint infections",
  "Prevention before some dental or surgical procedures in specific cases"],
 "Generally well tolerated.",
 [g(C, ["Diarrhoea", "Nausea", "Thrush"]), g(U, ["Rash", "Itch"]),
  g(R, ["<b>Anaphylaxis</b>", "<b>C. difficile diarrhoea</b>", "<b>Severe skin reactions</b>"])],
 ["Swelling of the face or throat, or trouble breathing: call 000", "Severe or bloody diarrhoea", "Spreading redness with fever despite treatment"],
 ["Tell your doctor about any penicillin or cephalosporin allergy and what happened.", "With cellulitis, mark the edge of the redness with a pen so you can see if it’s spreading or shrinking.", "Lower doses may be needed in kidney disease."],
 [("Can I take cefalexin if I’m allergic to penicillin?", "Most people with a mild or uncertain penicillin allergy can. If you’ve had anaphylaxis or a severe skin reaction to penicillin, check with your doctor first."),
  ("How quickly does cefalexin work for cellulitis?", "You should see improvement within 2 to 3 days. The redness can spread a little in the first day before it improves; see your doctor if it keeps spreading or you feel worse."),
  ("Is cefalexin safe in pregnancy?", "Yes. It’s commonly used for urine and skin infections in pregnancy.")],
 [AMR, ("PBS: Cefalexin", PBS + "cefalexin"), ("ASCIA: Penicillin allergy", "https://www.allergy.org.au/patients/drug-allergy/penicillin-allergy")],
 REL + [("Boils and staph skin infections", "/boils/"), ("Urine infections (UTI)", "/uti/")])

med("doxycycline", "Doxycycline: Uses, Side Effects, Sun Sensitivity and How to Take It",
 "Doxycycline explained: chest infections, chlamydia, acne, rosacea, malaria prevention and tick-borne infections. Sun sensitivity, reflux and how to take it safely.",
 "Doxycycline", "Doxycycline",
 [("s", "Tetracycline antibiotic"), ("l", "Prescription only (S4)")],
 "A versatile antibiotic used for chest infections, chlamydia, acne, rosacea and malaria prevention. Take it upright with plenty of water, and watch the sun.",
 "Doxycycline treats a wide range of infections, from pneumonia and chlamydia to Q fever and tick-borne illnesses. At lower doses, it calms acne and rosacea. It must be swallowed with a full glass of water while upright, as it can burn the oesophagus, and it makes the skin burn easily in the sun.",
 [("For", "Chest infections, chlamydia, acne, rosacea, malaria prevention, Q fever and tick-borne infections"),
  ("Works", "Broad activity, including ‘atypical’ bacteria other antibiotics miss"),
  ("Cost", "PBS: $25 a script ($7.70 concession), often less"),
  ("Kicks in", "Infections in days; acne and rosacea over 6 to 12 weeks"),
  ("Dose", "Commonly 100 mg once or twice a day; 50 to 100 mg daily for acne"),
  ("Watch for", "Sunburn, heartburn, nausea")],
 "The Swiss Army knife of antibiotics, with a sunburn warning.",
 ["Doryx, Doxsig, Doxy, Vibramycin and generics"],
 "Doxycycline stops bacteria making proteins. It also has anti-inflammatory effects, which is why low doses help acne and rosacea.",
 ["Community-acquired pneumonia and chest infections",
  "Chlamydia and some other sexually transmitted infections; doxy-PEP for STI prevention in some groups",
  "Acne and rosacea",
  "Malaria prevention when travelling",
  "Q fever, Lyme disease and rickettsial infections (e.g. Queensland tick typhus)",
  "Cellulitis caused by MRSA (sometimes)"],
 "Mostly gut and skin side effects, and oesophagus irritation if not taken properly.",
 [g(C, ["Nausea and indigestion", "<b>Sun sensitivity</b> (sunburn)", "Diarrhoea"]),
  g(U, ["<b>Oesophageal ulcers</b> (pain swallowing)", "Thrush", "Headache"]),
  g(R, ["Raised pressure in the head (headache, blurred vision)", "Nail separation in the sun", "<b>Severe skin reactions</b>"])],
 ["Painful swallowing or chest pain after a dose", "Severe headache with vision changes", "Blistering rash or severe sunburn"],
 ["Swallow with a full glass of water, sitting or standing, and don’t lie down for 30 minutes.", "Take with food if it upsets your stomach; avoid taking with antacids, iron or calcium (separate by 2 to 3 hours).", "Use strong sun protection.", "Usually avoided in pregnancy and young children, but short courses are used when needed (e.g. tick-borne infections)."],
 [("Why can’t I lie down after taking doxycycline?", "If the capsule sticks in the oesophagus it can cause a painful ulcer. Take it upright with a full glass of water and stay upright for 30 minutes."),
  ("Does doxycycline make you sunburn?", "Yes. It increases sun sensitivity, so use sunscreen, a hat and cover up."),
  ("Can I take doxycycline with milk?", "Calcium reduces absorption somewhat. Taking it with a meal is fine, but avoid dairy, antacids, iron and calcium supplements around the dose.")],
 [AMR, ("PBS: Doxycycline", PBS + "doxycycline"), ("Australian Immunisation Handbook / travel: Malaria prevention (Healthdirect)", "https://www.healthdirect.gov.au/malaria")],
 REL + [("Acne", "/acne/"), ("Rosacea", "/rosacea/")])

med("uti-antibiotics", "UTI Antibiotics: Trimethoprim, Nitrofurantoin, Cefalexin and Fosfomycin",
 "Antibiotics for urine infections (UTI) explained: trimethoprim, nitrofurantoin, cefalexin and fosfomycin. Course length, side effects, pregnancy and recurrent UTIs.",
 "Antibiotics for urine infections (UTI)", "UTI antibiotics",
 [("s", "Antibiotics"), ("l", "Prescription only (S4); some pharmacist-supplied")],
 "Short courses of antibiotic clear most uncomplicated bladder infections in women within a few days. Pharmacists in several states can now supply some of them.",
 "Uncomplicated bladder infections (cystitis) in women are usually treated with trimethoprim for 3 days, nitrofurantoin for 5 days, or cefalexin for 5 days. Men, pregnant women, kidney infections and recurrent infections need longer or different treatment. A urine culture helps when infections keep coming back or don’t respond.",
 [("For", "Bladder infections (cystitis); some for kidney infections or prevention"),
  ("Works", "Symptoms usually settle within 1 to 3 days"),
  ("Cost", "PBS: $25 a script ($7.70 concession), often less"),
  ("Kicks in", "Within a day or two"),
  ("Dose", "Trimethoprim 300 mg once daily for 3 days (women, uncomplicated)"),
  ("Watch for", "Nausea, rash; fever or back pain means see a doctor")],
 "Short, sharp and usually effective. Fever or loin pain changes the game.",
 ["Trimethoprim: Alprim, Triprim. Nitrofurantoin: Macrodantin, Furadantin. Cefalexin: Keflex. Fosfomycin: Monurol. Amoxicillin-clavulanate: Augmentin"],
 "Each works in a different way, but all reach high levels in urine. Nitrofurantoin barely enters the bloodstream, so it’s only for bladder infections, not kidney infections.",
 ["Uncomplicated bladder infections in women: trimethoprim (3 days), nitrofurantoin (5 days) or cefalexin (5 days)",
  "Pregnancy: cefalexin, nitrofurantoin (not near term) or amoxicillin-clavulanate, guided by culture",
  "Men: usually 7 days, and a urine culture",
  "Kidney infection: different antibiotics and longer courses, sometimes hospital",
  "Fosfomycin: a single dose, mostly for resistant bacteria",
  "Low-dose prevention for recurrent UTIs in some people"],
 "Usually mild.",
 [g(C, ["Nausea", "Rash and itch", "Headache", "Thrush"]),
  g(U, ["High potassium (trimethoprim, especially with some blood pressure medicines)", "Dark yellow or brown urine (nitrofurantoin, harmless)"]),
  g(R, ["<b>Lung or liver reactions</b> with long-term nitrofurantoin", "<b>Low blood counts</b> (trimethoprim)", "<b>Severe skin reactions</b>"])],
 ["Fever, shivers, back or side pain, or vomiting: possible kidney infection, see a doctor today", "No improvement after 48 hours", "Blood in the urine that persists after treatment"],
 ["Drink normally; there’s no need to force fluids.", "See a doctor if you’re pregnant, male, have symptoms coming back, or have kidney disease.", "Nitrofurantoin isn’t suitable with poor kidney function.", "For recurrent UTIs, ask about non-antibiotic options too (vaginal oestrogen after menopause, methenamine)."],
 [("How long do UTI antibiotics take to work?", "Most people feel better within 1 to 2 days. If you’re not improving after 48 hours, or develop fever or back pain, see a doctor."),
  ("Can I get UTI antibiotics from a pharmacist?", "In several Australian states, pharmacists can now supply antibiotics for uncomplicated UTIs in women aged about 18 to 65 under specific rules."),
  ("Why is my urine brown on nitrofurantoin?", "Nitrofurantoin can turn urine dark yellow or brown. It’s harmless.")],
 [AMR, ("PBS: Trimethoprim", PBS + "trimethoprim"), ("PBS: Nitrofurantoin", PBS + "nitrofurantoin")],
 [("Urine infections (UTI)", "/uti/"), ("Antibiotics", "/antibiotics/"), ("Cefalexin", "/medicines/cefalexin/")])
